        data: {"result": {"minY": 0.08333333333333333, "minX": 1.75833234E12, "maxY": 13.55, "series": [{"data": [[1.75833252E12, 10.183333333333334], [1.75833234E12, 5.483333333333333], [1.75833246E12, 13.116666666666667], [1.7583324E12, 13.55], [1.75833258E12, 2.45]], "isOverall": false, "label": "Transaction-success", "isController": false}, {"data": [[1.75833252E12, 1.0], [1.75833258E12, 0.08333333333333333]], "isOverall": false, "label": "Transaction-failure", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 60000, "maxX": 1.75833258E12, "title": "Total Transactions Per Second"}},
